const STEP_NAMES={offer:'Offer',extras:'Extras',hotels:'Hotel',transfer:'Transfer',upsell:'Experiences',apis:'Travelers',seats:'Seats',payment:'Payment',confirmation:'Confirmed',documents:'Documents'};
