function groupBaseOffer(group){return (S.filters.cabin!=='any'&&arr(group.items).find(item=>legCabin(item,group.leg)===S.filters.cabin))||group.items[0]}
function groupSuggestion(group){return arr(group.items).filter(o=>S.filters.cabin==='any'||legCabin(o,group.leg)===S.filters.cabin).map(o=>S.suggestions.get(str(o.id||o.offerId))).filter(Boolean).sort((a,b)=>(TIER_RANK[b.tier]-TIER_RANK[a.tier])||(a.price-b.price)||(a.duration-b.duration))[0]||null}
function filterFlightGroups(groups){const f=S.filters;return groups.filter(g=>{if(g.kind!=='flight')return true;const slice=arr(g.items[0].slices)[g.leg],stops=legStops(slice);if(f.stops!=='any'&&(stops===null||(f.stops==='2+'?stops<2:stops!==Number(f.stops))))return false;if(f.airlines.length&&!g.items.some(item=>legAirlines(item,g.leg).some(c=>f.airlines.includes(str(c.iataCode).toUpperCase()))))return false;if(f.cabin!=='any'&&!g.items.some(item=>legCabin(item,g.leg)===f.cabin))return false;return true})}
