function durationText(minutes){if(minutes===null||!Number.isFinite(minutes)||minutes<0)return '';const h=Math.floor(minutes/60),m=Math.round(minutes%60);return [h?`${h}h`:'',m?`${m}m`:(!h?'0m':'')].filter(Boolean).join(' ')}
