function cabinFor(offer){const classes=[...new Set(arr(offer.slices).flatMap(s=>arr(s.segments)).map(s=>str(arr(s.passengers)[0]?.cabinClass).toLowerCase()).filter(Boolean))];return classes.length>1?'mixed':classes[0]||'unknown'}
